<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import MarkdownIt from 'markdown-it'
import katex from 'katex'
import { AlertCircle, ArrowRight, BookOpen, Check, ChevronDown, FileText, LoaderCircle, LockKeyhole, MessageSquarePlus, PanelRightClose, Send, Sparkles, Square, Trash2, X } from 'lucide-vue-next'
import RagAuthGate from '../components/RagAuthGate.vue'
import { authState, ragRequest, ragPath, clearCredentials } from '../rag/api'

type KB = {id:string; name:string; course_name:string; document_count:number}
type Citation = {citation_id:string; document_id:string; document_name:string; chunk_id:string; page_start:number|null; page_end:number|null; section_title:string; snippet:string; retrieval_score:number; preview_url:string}
type AnswerMode = 'library'|'model'
type ChatSession = {id:string; knowledge_base_id:string|null; answer_mode:AnswerMode; title:string; updated_at:string}
type ChatMessage = {id?:string; role:'user'|'assistant'; content:string; citations?:Citation[]; loading?:boolean; error?:string; feedback?:string}
const md = new MarkdownIt({ html: false, linkify: true, breaks: true, typographer: true })
const authenticated=ref(false); const validatingAuth=ref(!!authState.token); const knowledgeBases=ref<KB[]>([]); const selectedKb=ref(''); const answerMode=ref<AnswerMode>('library'); const sessions=ref<ChatSession[]>([]); const activeSession=ref(''); const messages=ref<ChatMessage[]>([])
const input=ref(''); const busy=ref(false); const loading=ref(false); const error=ref(''); const chatBox=ref<HTMLElement>(); const preview=ref<{document_name:string;page:number|null;page_end?:number|null;section_title?:string;text:string;highlight?:string}|null>(null); const previewBusy=ref(false)
let aborter:AbortController|undefined; let pollTimer:number|undefined
const selectedKnowledgeBase=computed(()=>knowledgeBases.value.find(kb=>kb.id===selectedKb.value))
const latestCitations=computed(()=>messages.value.at(-1)?.citations||[])
const prompts=computed(()=>answerMode.value==='library'?['解释这份资料中的核心概念','总结文档里最重要的定义和结论','比较资料中提到的两种方法']:['解释一个核心概念并举例','帮我梳理这个问题的解题步骤','比较两种方法的适用场景'])
function renderMarkdown(text:string){
  const math: string[] = []; const marker=`SPMATH${crypto.randomUUID().replace(/-/g,'')}TOKEN`
  const prepared=text.replace(/\$\$([\s\S]+?)\$\$|\$([^$\n]+)\$/g,(_match,block:string|undefined,inline:string|undefined)=>{
    const source=(block||inline||'').trim()
    try{math.push(katex.renderToString(source,{displayMode:Boolean(block),throwOnError:false,trust:false}))}
    catch{math.push(source)}
    return `${marker}${math.length-1}ENDMATH`
  })
  const rendered=md.render(prepared)
  return rendered.replace(new RegExp(`${marker}(\\d+)ENDMATH`,'g'),(_match,index:string)=>math[Number(index)]||'')
}
function authDone(){authenticated.value=true;loadKnowledgeBases()}
function logout(){clearCredentials();authenticated.value=false;knowledgeBases.value=[];sessions.value=[];messages.value=[]}
function expireAuth(){logout();error.value='登录状态已过期，请重新登录'}
async function loadKnowledgeBases(){try{knowledgeBases.value=await ragRequest<KB[]>('/knowledge-bases');if(!selectedKb.value||!knowledgeBases.value.some(k=>k.id===selectedKb.value)) selectedKb.value=knowledgeBases.value[0]?.id||''}catch(e){error.value=e instanceof Error?e.message:'无法读取知识库'}}
async function loadSessions(){if(answerMode.value==='library'&&!selectedKb.value){sessions.value=[];return}const params=new URLSearchParams({answer_mode:answerMode.value});if(answerMode.value==='library')params.set('knowledge_base_id',selectedKb.value);try{sessions.value=await ragRequest<ChatSession[]>(`/rag/sessions?${params.toString()}`)}catch(e){error.value=e instanceof Error?e.message:'无法读取对话'}}
async function selectSession(id:string){activeSession.value=id;loading.value=true;error.value='';try{messages.value=await ragRequest<ChatMessage[]>(`/rag/sessions/${id}/messages`)}catch(e){error.value=e instanceof Error?e.message:'无法读取历史消息'}finally{loading.value=false;scrollDown()}}
async function createSession(){if(answerMode.value==='library'&&!selectedKb.value){error.value='请先创建或选择一个知识库';return}try{const session=await ragRequest<ChatSession>('/rag/sessions',{method:'POST',body:JSON.stringify({knowledge_base_id:answerMode.value==='library'?selectedKb.value:'',answer_mode:answerMode.value,title:'新建学习对话'})});activeSession.value=session.id;messages.value=[];await loadSessions()}catch(e){error.value=e instanceof Error?e.message:'新建对话失败'}}
async function changeAnswerMode(mode:AnswerMode){if(busy.value||mode===answerMode.value)return;answerMode.value=mode;activeSession.value='';messages.value=[];error.value='';await loadSessions()}
async function deleteSession(session:ChatSession){if(!window.confirm(`删除对话“${session.title}”？`))return;try{await ragRequest(`/rag/sessions/${session.id}`,{method:'DELETE'});sessions.value=sessions.value.filter(item=>item.id!==session.id);if(activeSession.value===session.id){activeSession.value='';messages.value=[]}}catch(e){error.value=e instanceof Error?e.message:'删除失败'}}
async function scrollDown(){await nextTick();chatBox.value?.scrollTo({top:chatBox.value.scrollHeight,behavior:'smooth'})}
function readSseBlock(block:string,onEvent:(name:string,data:any)=>void){let eventName='message';const data:string[]=[];for(const line of block.split(/\r?\n/)){if(line.startsWith('event:'))eventName=line.slice(6).trim();else if(line.startsWith('data:'))data.push(line.slice(5).trim())}if(!data.length)return;const value=data.join('\n');try{onEvent(eventName,JSON.parse(value))}catch{onEvent(eventName,value)}}
async function sendQuestion(raw=input.value, retryIndex?:number){const question=raw.trim();if(!question||busy.value)return;error.value='';if(!activeSession.value)await createSession();if(!activeSession.value)return
  let assistantIndex:number
  if(retryIndex!==undefined){assistantIndex=retryIndex;messages.value[assistantIndex]={role:'assistant',content:'',citations:[],loading:true}}
  else{messages.value.push({role:'user',content:question});messages.value.push({role:'assistant',content:'',citations:[],loading:true});assistantIndex=messages.value.length-1;input.value=''}
  busy.value=true;aborter=new AbortController();await scrollDown()
  try{
    const token=authState.token;const response=await fetch(ragPath('/rag/chat/stream'),{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify({session_id:activeSession.value,question}),signal:aborter.signal})
    if(response.status===401){logout();throw new Error('登录状态已失效，请重新登录')}
    if(!response.ok){let detail=`请求失败 (${response.status})`;try{detail=(await response.json()).detail||detail}catch{};throw new Error(detail)}
    if(!response.body)throw new Error('浏览器不支持流式响应')
    const reader=response.body.getReader();const decoder=new TextDecoder();let buffer='';let completed=false
    while(true){const {value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let boundary:number;while((boundary=buffer.indexOf('\n\n'))>=0){const block=buffer.slice(0,boundary);buffer=buffer.slice(boundary+2);readSseBlock(block,(name,data)=>{const target=messages.value[assistantIndex];if(!target)return;if(name==='citations')target.citations=data;if(name==='delta')target.content+=data;if(name==='done'){target.id=data.message_id;target.content=typeof data.answer==='string'?data.answer:'';target.loading=false;target.error='';completed=true}if(name==='error'){const message=typeof data.message==='string'&&data.message?data.message:'回答生成失败';target.loading=false;target.error=message;error.value=message}});void scrollDown()}}
    if(!completed&&!messages.value[assistantIndex].error)messages.value[assistantIndex].error='连接中断，服务端未保存本轮回答。可重试。'
    await loadSessions()
  }catch(e){const target=messages.value[assistantIndex];target.loading=false;if((e as Error).name==='AbortError')target.error='已中断生成';else{target.error=e instanceof Error?e.message:'问答请求失败';error.value=target.error}}
  finally{busy.value=false;aborter=undefined;await scrollDown()}}
function stopGeneration(){aborter?.abort()}
function retry(messageIndex:number){const question=messages.value[messageIndex-1]?.content;if(question)void sendQuestion(question,messageIndex)}
async function rateAnswer(message:ChatMessage,rating:'helpful'|'unhelpful'){if(!message.id)return;try{await ragRequest(`/rag/messages/${message.id}/feedback`,{method:'PUT',body:JSON.stringify({rating})});message.feedback=rating}catch(e){error.value=e instanceof Error?e.message:'评价提交失败'}}
async function openCitation(citation:Citation){preview.value=null;previewBusy.value=true;try{preview.value=await ragRequest(`/documents/${citation.document_id}/preview?chunk_id=${encodeURIComponent(citation.chunk_id)}`)}catch(e){error.value=e instanceof Error?e.message:'无法打开原文'}finally{previewBusy.value=false}}
watch(selectedKb,async()=>{if(answerMode.value!=='library')return;activeSession.value='';messages.value=[];await loadSessions()})
onMounted(async()=>{window.addEventListener('studypath:auth-expired',expireAuth);if(authState.token){try{await ragRequest('/auth/me');authenticated.value=true;await loadKnowledgeBases()}catch{clearCredentials()}finally{validatingAuth.value=false}}else validatingAuth.value=false})
onBeforeUnmount(()=>{aborter?.abort();window.clearInterval(pollTimer);window.removeEventListener('studypath:auth-expired',expireAuth)})
</script>

<template>
  <div v-if="validatingAuth" class="rag-auth-wrap"><div class="rag-library-loading"><LoaderCircle class="spin"/>正在验证登录状态…</div></div>
  <div v-else-if="!authenticated" class="rag-auth-wrap"><RagAuthGate @authenticated="authDone"/></div>
  <section v-else class="rag-chat-page">
    <aside class="rag-session-rail">
      <div class="rag-rail-heading"><div><span class="rag-eyebrow">AI STUDY ASSISTANT</span><h2>智能答疑</h2></div><button class="rag-icon-button" title="退出登录" @click="logout"><X :size="16"/></button></div>
      <button class="rag-button primary wide" :disabled="answerMode==='library'&&!selectedKb" @click="createSession"><MessageSquarePlus :size="16"/>新建对话</button>
      <div class="rag-mode-field">
        <span class="rag-mode-label">回答方式</span>
        <div class="rag-mode-options" role="group" aria-label="选择回答方式">
          <button type="button" class="rag-mode-option" :class="{selected:answerMode==='library'}" :aria-pressed="answerMode==='library'" @click="changeAnswerMode('library')"><BookOpen :size="14"/>本地资料库</button>
          <button type="button" class="rag-mode-option" :class="{selected:answerMode==='model'}" :aria-pressed="answerMode==='model'" @click="changeAnswerMode('model')"><Sparkles :size="14"/>大模型</button>
        </div>
      </div>
      <label v-if="answerMode==='library'" class="rag-field rag-kb-select"><span>检索知识库</span><div><BookOpen :size="15"/><select v-model="selectedKb"><option value="" disabled>选择知识库</option><option v-for="kb in knowledgeBases" :key="kb.id" :value="kb.id">{{kb.name}}{{kb.course_name?` · ${kb.course_name}`:''}}</option></select><ChevronDown :size="14"/></div></label>
      <div class="rag-session-title">最近对话 <span>{{sessions.length}}</span></div>
      <div class="rag-session-list"><button v-for="session in sessions" :key="session.id" class="rag-session-item" :class="{selected:activeSession===session.id}" @click="selectSession(session.id)"><MessageSquarePlus :size="15"/><span>{{session.title}}</span><span class="rag-session-delete" title="删除对话" @click.stop="deleteSession(session)"><Trash2 :size="14"/></span></button><div v-if="!sessions.length" class="rag-empty-note">这里会显示你保存的学习对话。</div></div>
      <div class="rag-private-note"><LockKeyhole :size="14"/><span>此账号的资料与历史对话和其他账号隔离。</span></div>
    </aside>
    <main class="rag-chat-main">
      <header class="rag-chat-header"><div><span class="rag-eyebrow">{{answerMode==='library'?(selectedKnowledgeBase?.course_name||'个人知识库'):'通用知识问答'}}</span><h1>{{sessions.find(s=>s.id===activeSession)?.title||(answerMode==='library'?'课程资料问答':'大模型问答')}}</h1><p>{{answerMode==='library'?'回答依据当前知识库检索到的原文，来源可打开核对。':'由大模型根据已有知识直接回答，不会检索本地资料。'}}</p></div><a v-if="answerMode==='library'" class="rag-button subtle" href="/library"><FileText :size="15"/>管理资料</a></header>
      <div v-if="answerMode==='library'&&!knowledgeBases.length" class="rag-empty-state"><div class="rag-empty-icon"><BookOpen/></div><h3>先创建知识库并上传课程资料</h3><p>资料完成解析和向量索引后，才能基于原文进行问答。</p><a class="rag-button primary" href="/library">前往学习资料库 <ArrowRight :size="15"/></a></div>
      <div v-else-if="answerMode==='library'&&selectedKnowledgeBase?.document_count===0" class="rag-inline-alert"><AlertCircle :size="17"/><span>当前知识库还没有可用资料。请先上传并等待索引状态变为“已就绪”。</span><a href="/library">前往上传</a></div>
      <div v-else ref="chatBox" class="rag-message-scroll">
        <div v-if="!messages.length" class="rag-welcome"><span class="rag-welcome-spark"><Sparkles :size="20"/></span><h2>{{answerMode==='library'?'从课程资料出发，弄懂每一个问题':'直接向大模型提问，探索更多知识'}}</h2><p>{{answerMode==='library'?'答案会附上真实文档片段与页码。试着问：':'大模型将依据已有知识回答，不会引用本地资料。试着问：'}}</p><div class="rag-prompt-grid"><button v-for="prompt in prompts" :key="prompt" @click="input=prompt">{{prompt}} <ArrowRight :size="14"/></button></div></div>
        <article v-for="(message,index) in messages" :key="message.id||`local-${index}`" class="rag-message" :class="message.role">
          <div class="rag-avatar"><span v-if="message.role==='user'">我</span><Sparkles v-else :size="15"/></div><div class="rag-message-body"><div class="rag-message-label">{{message.role==='user'?'你':'智学研途'}}</div><div v-if="message.role==='user'" class="rag-user-bubble">{{message.content}}</div><template v-else><div class="rag-assistant-content" v-html="renderMarkdown(message.content)"/><div v-if="message.loading" class="rag-generating"><LoaderCircle :size="14" class="spin"/>{{answerMode==='library'?'正在依据资料组织回答…':'正在由大模型生成回答…'}}</div><div v-if="message.id&&!message.loading&&!message.error" class="rag-message-feedback"><span>回答有帮助吗？</span><button :class="{active:message.feedback==='helpful'}" @click="rateAnswer(message,'helpful')">有帮助</button><button :class="{active:message.feedback==='unhelpful'}" @click="rateAnswer(message,'unhelpful')">需改进</button></div><div v-if="message.citations?.length" class="rag-message-citations"><button v-for="(citation,citeIndex) in message.citations" :key="citation.citation_id" @click="openCitation(citation)"><span>{{citeIndex+1}}</span>{{citation.document_name}}<small>{{citation.page_start?`第 ${citation.page_start} 页`:'片段'}}</small></button></div><div v-if="message.error" class="rag-message-error"><AlertCircle :size="14"/>{{message.error}}<button @click="retry(index)">重试</button></div></template></div>
        </article>
      </div>
      <div v-if="error" class="rag-global-error"><AlertCircle :size="15"/>{{error}}<button @click="error=''">关闭</button></div>
      <form v-if="answerMode==='model'||knowledgeBases.length" class="rag-composer" @submit.prevent="sendQuestion()"><textarea v-model="input" rows="2" maxlength="5000" :placeholder="answerMode==='library'?'输入课程问题，按 Enter 发送，Shift + Enter 换行':'输入问题，按 Enter 发送，Shift + Enter 换行'" :disabled="busy||(answerMode==='library'&&selectedKnowledgeBase?.document_count===0)" @keydown.enter.exact.prevent="sendQuestion()"/><div class="rag-composer-bottom"><span>{{answerMode==='library'?'检索片段将发送至已配置的大模型服务；请勿上传未获授权的敏感资料。':'此模式直接使用已配置的大模型服务，不检索本地资料。'}}</span><button v-if="busy" type="button" class="rag-button stop" @click="stopGeneration"><Square :size="13"/>中断</button><button v-else class="rag-button primary send" :disabled="!input.trim()||(answerMode==='library'&&selectedKnowledgeBase?.document_count===0)"><Send :size="15"/>发送</button></div></form>
    </main>
    <aside class="rag-evidence-rail"><div class="rag-evidence-head"><div><span class="rag-eyebrow">{{answerMode==='library'?'GROUNDED ANSWERS':'MODEL ANSWERS'}}</span><h3>{{answerMode==='library'?'参考来源':'回答模式'}}</h3></div><span class="rag-source-count">{{latestCitations.length}}</span></div><p class="rag-evidence-hint">{{answerMode==='library'?'来源来自本轮真实检索结果。匹配分是检索分数，不代表答案正确概率。':'大模型依据已有知识回答，不读取本地资料库，因此不会显示文档引用。'}}</p><div v-if="latestCitations.length" class="rag-evidence-list"><button v-for="(citation,index) in latestCitations" :key="citation.citation_id" class="rag-evidence-card" @click="openCitation(citation)"><span class="rag-evidence-index">{{String(index+1).padStart(2,'0')}}</span><b>{{citation.document_name}}</b><small>{{citation.page_start?`第 ${citation.page_start}${citation.page_end&&citation.page_end!==citation.page_start?`–${citation.page_end}`:''} 页`:citation.section_title||'页码未标注'}}</small><span v-if="citation.section_title" class="rag-evidence-section">{{citation.section_title}}</span><p>{{citation.snippet}}</p><span class="rag-evidence-score">检索分数 {{citation.retrieval_score.toFixed(3)}} · 点击查看原文</span></button></div><div v-else class="rag-evidence-empty"><PanelRightClose :size="20"/><p>{{answerMode==='library'?'发送问题后，这里会列出检索到的原文和页码。':'切换到本地资料库模式后，可查看回答引用的原文。'}}</p></div><div class="rag-evidence-foot"><Check :size="14"/>{{answerMode==='library'?'引用由服务端文档片段生成':'当前回答未使用本地资料'}}</div></aside>
    <div v-if="preview||previewBusy" class="rag-modal-backdrop" @click.self="preview=null"><section class="rag-preview-modal"><header><div><span class="rag-eyebrow">原文定位</span><h3>{{preview?.document_name||'正在打开资料'}}</h3><small v-if="preview?.page">第 {{preview.page}}{{preview.page_end&&preview.page_end!==preview.page?`–${preview.page_end}`:''}} 页 · {{preview.section_title||'未识别章节'}}</small></div><button class="rag-icon-button" @click="preview=null"><X :size="17"/></button></header><div v-if="previewBusy" class="rag-preview-loading"><LoaderCircle class="spin"/>正在读取保存的原文…</div><div v-else class="rag-preview-text"><div v-if="preview?.highlight" class="rag-original-quote"><b>检索引用片段</b><blockquote>{{preview.highlight}}</blockquote></div><div class="rag-preview-page-label">{{preview?.page?`文档第 ${preview.page} 页原文`:'解析后的文档文本'}}</div><pre>{{preview?.text}}</pre><p class="rag-muted">页码来自原始文档提取；当前显示提取文本，精确版面高亮暂不可用。</p></div></section></div>
  </section>
</template>

<style>
@import 'katex/dist/katex.min.css';
.rag-chat-page{display:grid;grid-template-columns:230px minmax(0,1fr) 292px;gap:16px;min-height:calc(100vh - 166px);height:calc(100vh - 166px);color:#28253a}.rag-session-rail,.rag-evidence-rail,.rag-chat-main{background:#fff;border:1px solid #ece9f2;border-radius:18px;box-shadow:0 4px 18px #32245c08}.rag-session-rail{padding:18px 14px;display:flex;flex-direction:column;min-height:0}.rag-rail-heading,.rag-evidence-head,.rag-chat-header,.rag-preview-modal header{display:flex;align-items:center;justify-content:space-between;gap:12px}.rag-rail-heading{margin:2px 2px 18px}.rag-rail-heading h2,.rag-chat-header h1,.rag-evidence-head h3,.rag-preview-modal h3{margin:4px 0 0;letter-spacing:-.025em}.rag-rail-heading h2{font-size:19px}.rag-eyebrow{font-size:10px;letter-spacing:.12em;color:#8c73d8;font-weight:700}.rag-button,.rag-icon-button,.rag-link-button{border:0;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:8px;font:inherit;text-decoration:none}.rag-button{min-height:38px;border-radius:10px;padding:0 13px;font-size:12px;font-weight:650}.rag-button.primary{color:white;background:linear-gradient(120deg,#7048dc,#8b68ef);box-shadow:0 5px 12px #7953df29}.rag-button.primary:disabled{opacity:.5;cursor:not-allowed}.rag-button.wide{width:100%}.rag-button.subtle{background:#f6f3fd;color:#7557ca}.rag-button.stop{background:#fff0f0;color:#b74958}.rag-button.send{margin-left:auto}.rag-icon-button{width:32px;height:32px;border-radius:9px;background:#f6f4fa;color:#77718a}.rag-field{display:grid;gap:7px;margin:18px 0 20px}.rag-field>span{font-size:11px;color:#888299}.rag-kb-select>div{display:flex;align-items:center;gap:8px;border:1px solid #ece9f3;border-radius:10px;padding:0 10px;color:#8064cf}.rag-kb-select select{height:39px;min-width:0;flex:1;border:0;background:transparent;color:#423c55;outline:0;font-size:12px}.rag-session-title{display:flex;justify-content:space-between;padding:0 4px 8px;color:#8b8598;font-size:11px}.rag-session-title span,.rag-so